-- A7 — student notebook (notes on a lesson), course announcements, and the old site's 26 announcements.
-- Additive only and idempotent. Apply AFTER A6 and BEFORE deploying the code that uses it:
--   node scripts/apply-app-sql.mjs prisma/app-sql/A7-notes-announcements.sql [--dry-run]

-- ── Notes a student writes under a lesson video (private to the student; "at 03:25" = position_secs) ──
CREATE TABLE IF NOT EXISTS lesson_notes (
  id            uuid PRIMARY KEY,
  user_id       uuid        NOT NULL REFERENCES users(id),
  course_id     uuid        NOT NULL REFERENCES courses(id),
  lesson_id     uuid        NOT NULL REFERENCES lessons(id),
  body          text        NOT NULL,
  position_secs integer     NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz NULL
);
CREATE INDEX IF NOT EXISTS lesson_notes_user_idx ON lesson_notes (user_id, course_id, created_at DESC);

-- ── Course announcements (instructor → the course's students) ──
CREATE TABLE IF NOT EXISTS course_announcements (
  id           uuid PRIMARY KEY,
  course_id    uuid         NOT NULL REFERENCES courses(id),
  author_id    uuid         NULL REFERENCES users(id),
  title        varchar(255) NOT NULL,
  body         text         NOT NULL,
  legacy_wp_id bigint       NULL UNIQUE,
  created_at   timestamptz  NOT NULL DEFAULT now(),
  updated_at   timestamptz  NOT NULL DEFAULT now(),
  deleted_at   timestamptz  NULL
);
CREATE INDEX IF NOT EXISTS course_announcements_course_idx ON course_announcements (course_id, created_at DESC);

-- ── The old site's announcements (Tutor tutor_announcements, all published): (post id, course post id,
--    author user id, posted at (UTC), title, text). Title and text are base64 (UTF-8) so no quote, dash or
--    semicolon inside them can break this file. Rows whose course is not in this database are skipped.
INSERT INTO course_announcements (id, course_id, author_id, title, body, legacy_wp_id, created_at, updated_at)
